const fs = require('fs');
const path = require('path');
const { ROOT, CONTRACT_ROOT, loadPlacementContracts } = require('./placement-validator');

const contracts = loadPlacementContracts();
const schemaCount = fs.readdirSync(path.join(CONTRACT_ROOT, 'schemas')).filter((file) => file.endsWith('.json')).length;
const scenarioCount = fs.readdirSync(path.join(ROOT, 'test-scenarios', 'placement')).filter((file) => file.endsWith('.json')).length;
const lines = [
  '# Template Builder Placement Contract Analysis', '',
  'Generated by a standalone read-only tool. No asset, application, database, or runtime is modified.', '',
  '## Coverage', '',
  `- JSON Schemas: ${schemaCount}`,
  `- Website sections: ${Object.keys(contracts.sections.sections).length}`,
  `- Industry profiles: ${Object.keys(contracts.industries.industries).length}`,
  `- Asset-type defaults: ${Object.keys(contracts.defaults.asset_types).length}`,
  `- Positive/negative fixtures: ${scenarioCount}`,
  '- Provider connections: 0',
  '- Runtime integrations: 0', '',
  '## Readiness', '',
  '- Contract-layer scope: complete.',
  '- Standalone module integration preparation: 94%.',
  '- SaaS attachment: not authorized and not implemented.', '',
  'Remaining gates are documented in the canonical `INTEGRATION_READINESS.md`: real-template visual QA, pinned production JSON Schema validator, performance/browser evidence, platform authorization/licensing contracts, rendering decision, threat model, and approved integration ADR.'
];

const output = path.join(ROOT, 'reports', 'placement-contract-analysis.md');
fs.writeFileSync(output, `${lines.join('\n')}\n`, 'utf8');
process.stdout.write(`Placement contract report generated: ${output}\n`);
